enum key_enum{
	KEY_RIGHT_ARROW, KEY_LEFT_ARROW, KEY_UP_ARROW, KEY_DOWN_ARROW,
	KEY_Z, KEY_X, KEY_R,
	KEYS_COUNT
};

/**
* Struct holding variables which changes state of the game
*/
struct GameState 
{
	GameState()
		:windowWidth(1000), windowHeight(1000)
	{
		for (int i = 0; i < KEYS_COUNT; i++)
			keys[i] = false;

		smoke_current_time = smoke_start_time = elapsed_time = 0.001f * (float)glutGet(GLUT_ELAPSED_TIME); // milliseconds => seconds
		useFlashlight = false;
		fog = false;
		firing = true;
		camera_free = true;
	}
	int windowWidth;    // set by reshape callback
	int windowHeight;   // set by reshape callback

	float elapsed_time;
	bool useFlashlight;
	bool fog;
	bool camera_free;
	bool keys[KEYS_COUNT];    // false

	bool firing;
	float smoke_current_time;
	float smoke_start_time;
};


